===== managed-network CLI imports =====
package ManagedNetwork::CLI;

use strict;
use warnings;

use File::Basename qw(basename);
use Moo;
use MooX::Options
  protect_argv => 0,
  flavour => [qw(require_order no_auto_abbrev)];
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Types::Standard qw(Bool);

use ManagedNetwork::Logger;
use ManagedNetwork::Validator;

option help => (
    is      => 'ro',
    isa     => Bool,
    default => sub { 0 },
    doc     => 'print usage',
);

sub _usage {
    print STDERR "usage: managed-network validate\n";
    return;
}

sub run {
    my ($self, @argv) = @_;

    local @ARGV = @argv;
    my $options = eval { __PACKAGE__->new_with_options() };
    if (!$options) {
        my $error = $@ || 'invalid command line';
        $error =~ s/\s+\z//;
        print STDERR "fatal: $error\n";
        return 1;
    }
    if ($options->help()) {
        _usage();
        return 0;
    }
    if (@ARGV != 1 || $ARGV[0] ne 'validate') {
        _usage();
        return 1;
    }

    my $logger = ManagedNetwork::Logger->new(
        active_level => $ENV{SYSTEMD_LOG_LEVEL} // 'error',
    );
    my $status = eval {
        ManagedNetwork::Validator->from_environment(logger => $logger)->validate();
    };
    if (!$status && $@) {
        my $error = $@;
        $error =~ s/\s+\z//;
        $logger->error($error);
        return 1;
    }
    return $status;
}

1;

