verify_target_zram_staging() {
  require_in_target "zram verification"

  # shellcheck disable=SC2016
  # shellcheck disable=SC2046 # zram_perl_modules emits the fixed manifest declared above.
  : "verify staged zram payload" /bin/sh -c '
set -eu
default_config=$1
ini_config=$2
tmpfiles_config=$3
setup_helper=$4
writeback_helper=$5
setup_unit=$6
writeback_unit=$7
writebackd_unit=$8
idle_timer=${9}
cold_timer=${10}
modprobe_file=${11}
modules_file=${12}
module_root=${13}
rsyslog_config=${14}
logrotate_config=${15}
shift 15

[ -r "$default_config" ]
[ -r "$ini_config" ]
[ -r "$tmpfiles_config" ]
[ -r "$rsyslog_config" ]
[ -r "$logrotate_config" ]
[ -x "$setup_helper" ]
[ -x "$writeback_helper" ]
[ -r "$setup_unit" ]
[ -r "$writeback_unit" ]
[ -r "$writebackd_unit" ]
[ -r "$idle_timer" ]
[ -r "$cold_timer" ]
[ -r "$modprobe_file" ]
[ -r "$modules_file" ]
[ -L /etc/systemd/system/multi-user.target.wants/zram-setup.service ]
[ -L /etc/systemd/system/multi-user.target.wants/zram-writebackd.service ]
[ -L /etc/systemd/system/timers.target.wants/zram-idle-writeback.timer ]
[ -L /etc/systemd/system/timers.target.wants/zram-cold-tier.timer ]
sh -n "$default_config"
PERL5LIB="$module_root" perl \
  -MMooX::HandlesVia \
  -MMooX::Log::Any \
  -MMooX::Options \
  -MMooX::TypeTiny \
  -MTypes::Path::Tiny \
  -MLog::Any \
  -e 1
for module in "$@"; do
  [ -r "$module_root/$module" ]
  PERL5LIB="$module_root" perl -c "$module_root/$module" >/dev/null
done
PERL5LIB="$module_root" perl -MZram::Config -e \
  "Zram::Config::load_config(\$ARGV[0]); Zram::Config::validate_config(require_sysfs => 0);" \
  "$ini_config"
PERL5LIB="$module_root" perl -c "$setup_helper" >/dev/null
PERL5LIB="$module_root" perl -c "$writeback_helper" >/dev/null
/usr/sbin/rsyslogd -N1 -f /etc/rsyslog.conf
/usr/sbin/logrotate --debug /etc/logrotate.conf
' sh \
    "${FILE_ZRAM_DEFAULT}" \
    "${FILE_ZRAM_CONFIG}" \
    "${FILE_ZRAM_TMPFILES}" \
    "${FILE_ZRAM_SETUP_HELPER}" \
    "${FILE_ZRAM_WRITEBACK_HELPER}" \
    "${FILE_ZRAM_SETUP_SERVICE}" \
    "${FILE_ZRAM_WRITEBACK_SERVICE}" \
