    "${FILE_MODPROBE_ZRAM}" \
    "${FILE_MODULES_LOAD_ZRAM}" \
    "${DIR_ZRAM_SITE_PERL}" \
    "${FILE_ZRAM_RSYSLOG}" \
    "${FILE_ZRAM_LOGROTATE}" \
    $(zram_perl_modules)
}

set_target_default_unit() {
