    60	        @ARGV == 1 or do {
    61	            $options->_usage();
    62	            return 1;
    63	        };
    64	        my $snapshot = eval { TimeshiftManaged::Snapshot->from_environment($ARGV[0]) };
    65	        if (!$snapshot) {
