    my $seen_space = 0;
    for (my $index = 0; $index < length($raw); $index++) {
        my $character = substr($raw, $index, 1);

        if ($state eq 'single') {
            if ($character eq q{'}) {
                $state = 'bare';
                $quoted = 1;
            }
            else {
