btrfs_family_fstab_record_for_mount() {
  bffrm_fstab_file=$1
  bffrm_mount_target=$2

  [ -r "$bffrm_fstab_file" ] || return 1
  case "$bffrm_mount_target" in
    /*) ;;
    *) return 1 ;;
  esac

  awk -v target="$bffrm_mount_target" '
    /^[[:space:]]*#/ {
      next
    }
    NF >= 4 && $2 == target {
      filesystem_type = $3
      mount_options = $4
    }
    END {
      if (filesystem_type != "") {
        print filesystem_type " " mount_options
      }
    }
  ' "$bffrm_fstab_file"
}

